ground_truth_sql:
SELECT "nct", "author", "year", "publication_type", "included_in_ma", "ici_class", "cancer_type", "ici_name"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Small Cell Lung' AND "ici_class" = 'PD-L1, CTLA-4' AND "included_in_ma" = 'Yes';

gt_sql_final:
SELECT "nct", "author", "year", "originial_publication_or_follow_up", "included_in_ma", "class_of_ici", "cancer_type", "name_of_ici"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Small Cell Lung' AND "class_of_ici" = 'PD-L1, CTLA-4' AND "included_in_ma" = 'Yes';
